WITH latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY job_title ORDER BY salary DESC, id) AS dedup_rank FROM employees QUALIFY dedup_rank = 1) SELECT s.id, s.full_name, s.email, s.dept_id, s.manager_id, s.hire_date, s.level, (SELECT SUM(e2.salary) FROM employees e2 WHERE e2.dept_id = s.dept_id) AS sum_employee_salary FROM latest s ORDER BY hire_date DESC NULLS LAST, level DESC
